package cli

import (
	"encoding/json"
	"fmt"
	"time"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

// catalogItemLD mirrors one entry of the schema.org ItemList emitted on a
// Flipkart search results page (verified live: only name/position/url are
// present — no price/rating/discount data on the search surface).
type catalogItemLD struct {
	Name     string `json:"name"`
	Position int    `json:"position"`
	URL      string `json:"url"`
}

type itemListLD struct {
	ItemListElement []catalogItemLD `json:"itemListElement"`
}

func newCatalogDiffCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "diff <query>",
		Short: "Re-run a saved catalog search and show what's new, removed, or reordered since last time.",
		Long: `Re-runs the given search query live and compares the ordered result list
against the most recent snapshot stored locally for this exact query
string. Honest limitation: this diff is title/URL/position-only — Flipkart's
search results page carries no price data to diff against.`,
		Example:     `  flipkart-pp-cli catalog diff "wireless earbuds"`,
		Annotations: map[string]string{"pp:endpoint": "catalog.diff", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			query := args[0]

			if dryRunOK(flags) {
				fmt.Fprintf(cmd.ErrOrStderr(), "would search live catalog for %q and diff against the stored snapshot\n(dry run - no request sent)\n", query)
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c = c.WithTier("none")

			path := "/search"
			params := map[string]string{"q": query}
			data, err := c.Get(path, params)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			data, err = extractHTMLResponse(data, htmlExtractionOptions{
				Mode:           "embedded-json",
				BaseURL:        htmlExtractionRequestURL(c.BaseURL, path, params),
				ScriptSelector: "script#jsonLD",
				JSONPath:       "",
			})
			if err != nil {
				return fmt.Errorf("extracting search results JSON-LD: %w", err)
			}
			data = extractResponseData(data)

			var lists []itemListLD
			if err := json.Unmarshal(data, &lists); err != nil || len(lists) == 0 {
				return fmt.Errorf("no search results JSON-LD found for query %q", query)
			}
			items := lists[0].ItemListElement

			snapshot := make([]store.FlipkartSnapshotRow, 0, len(items))
			for _, it := range items {
				pid, _ := pidFromURL(it.URL) // best-effort; empty when unparseable
				snapshot = append(snapshot, store.FlipkartSnapshotRow{
					Position:  it.Position,
					ProductID: pid,
					Title:     it.Name,
					URL:       it.URL,
				})
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			prior, priorFetchedAt, err := db.LatestFlipkartSearchSnapshot(query)
			if err != nil {
				return fmt.Errorf("reading prior snapshot: %w", err)
			}

			now := time.Now()
			note := "diff is title/URL/position-only — search results carry no price data to compare"

			if len(prior) == 0 {
				if err := db.ReplaceFlipkartSearchSnapshot(query, snapshot, now); err != nil {
					return fmt.Errorf("storing baseline snapshot: %w", err)
				}
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"query":   query,
					"status":  "baseline_stored",
					"message": "no prior snapshot — nothing to diff yet, baseline stored",
					"items":   snapshot,
					"note":    note,
				}, flags)
			}

			priorByURL := make(map[string]store.FlipkartSnapshotRow, len(prior))
			for _, r := range prior {
				priorByURL[r.URL] = r
			}
			newByURL := make(map[string]store.FlipkartSnapshotRow, len(snapshot))
			for _, r := range snapshot {
				newByURL[r.URL] = r
			}

			var added, removed, reordered []map[string]any
			for _, r := range snapshot {
				if _, ok := priorByURL[r.URL]; !ok {
					added = append(added, map[string]any{"position": r.Position, "title": r.Title, "url": r.URL})
				}
			}
			for _, r := range prior {
				if _, ok := newByURL[r.URL]; !ok {
					removed = append(removed, map[string]any{"position": r.Position, "title": r.Title, "url": r.URL})
				}
			}
			for _, r := range snapshot {
				if old, ok := priorByURL[r.URL]; ok && old.Position != r.Position {
					reordered = append(reordered, map[string]any{
						"title":        r.Title,
						"url":          r.URL,
						"old_position": old.Position,
						"new_position": r.Position,
					})
				}
			}

			if err := db.ReplaceFlipkartSearchSnapshot(query, snapshot, now); err != nil {
				return fmt.Errorf("storing new snapshot: %w", err)
			}

			return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
				"query":               query,
				"status":              "diffed",
				"prior_snapshot_time": priorFetchedAt.UTC().Format(time.RFC3339),
				"new":                 emptyIfNil(added),
				"removed":             emptyIfNil(removed),
				"reordered":           emptyIfNil(reordered),
				"note":                note,
			}, flags)
		},
	}
	return cmd
}

func emptyIfNil(v []map[string]any) []map[string]any {
	if v == nil {
		return []map[string]any{}
	}
	return v
}
